def _normalize(text: str) -> str:
    return text.replace(" ", "").upper()

def _is_alnum_strict(text: str) -> bool:
    if not text:
        return False
    for ch in text:
        if not (("A" <= ch <= "Z") or ("0" <= ch <= "9")):
            return False
    return True

def _mod97_numeric_string(s: str) -> int:
    r = 0
    for ch in s:
        if "0" <= ch <= "9":
            r = (r * 10 + (ord(ch) - 48)) % 97
        else:  # A-Z
            v = ord(ch) - ord("A") + 10
            r = (r * 100 + v) % 97
    return r

def _check_digits(base: str) -> str:
    remainder = _mod97_numeric_string(base + "RF00")
    return f"{98 - remainder:02d}"

def rf_reference(base: str) -> str:
    if not isinstance(base, str):
        raise ValueError("base must be a string")
    normalized = _normalize(base)
    if not 1 <= len(normalized) <= 21 or not _is_alnum_strict(normalized):
        raise ValueError("base must be 1-21 alphanumeric characters")
    return "RF" + _check_digits(normalized) + normalized

def is_valid_rf_reference(text: str) -> bool:
    if not isinstance(text, str):
        return False
    normalized = _normalize(text)
    if not normalized.startswith("RF"):
        return False
    if not 5 <= len(normalized) <= 25:
        return False
    if not _is_alnum_strict(normalized):
        return False
    if not normalized[2:4].isdigit():
        return False
    rearranged = normalized[4:] + normalized[:4]
    if _mod97_numeric_string(rearranged) != 1:
        return False
    return normalized[2:4] == _check_digits(normalized[4:])
